import React, {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useState,
} from "react"

export type Theme = "light" | "dark"

interface ThemeContextType {
  theme: Theme
  setTheme: (theme: Theme) => void
  toggleTheme: () => void
  isDark: boolean
}

const ThemeContext = createContext<ThemeContextType | undefined>(undefined)

const STORAGE_KEY = "blog-theme"

function getPreferredTheme(): Theme {
  if (typeof window === "undefined") {
    return "light"
  }

  try {
    const stored = localStorage.getItem(STORAGE_KEY)
    if (stored === "light" || stored === "dark") {
      return stored
    }
  } catch {
    // Use the system preference when storage is unavailable.
  }

  return window.matchMedia?.("(prefers-color-scheme: dark)").matches
    ? "dark"
    : "light"
}

function getInitialTheme(): Theme {
  if (typeof document === "undefined") {
    return "light"
  }

  return document.documentElement.dataset.theme === "dark"
    ? "dark"
    : getPreferredTheme()
}

function applyTheme(theme: Theme): void {
  const root = document.documentElement
  if (theme === "dark") {
    root.setAttribute("data-theme", "dark")
  } else {
    root.removeAttribute("data-theme")
  }
  root.style.colorScheme = theme
}

interface ThemeProviderProps {
  children: React.ReactNode
}

export function ThemeProvider({ children }: ThemeProviderProps) {
  const [theme, setThemeState] = useState<Theme>(getInitialTheme)

  const setTheme = useCallback((newTheme: Theme) => {
    applyTheme(newTheme)
    try {
      localStorage.setItem(STORAGE_KEY, newTheme)
    } catch {
      // Keep the in-memory selection when storage is unavailable.
    }
    setThemeState(newTheme)
  }, [])

  const toggleTheme = useCallback(() => {
    // The head script may have applied a persisted theme before hydration, while
    // the server-rendered React state is still light. Read the DOM so the first
    // interaction always switches away from the theme currently on screen.
    const isDark = document.documentElement.dataset.theme === "dark"
    setTheme(isDark ? "light" : "dark")
  }, [setTheme])

  // Follow operating-system changes only until the visitor chooses a theme.
  useEffect(() => {
    const mediaQuery = window.matchMedia("(prefers-color-scheme: dark)")

    const handleChange = (event: MediaQueryListEvent) => {
      try {
        if (localStorage.getItem(STORAGE_KEY)) {
          return
        }
      } catch {
        // Without storage, system preference remains the source of truth.
      }

      const nextTheme = event.matches ? "dark" : "light"
      applyTheme(nextTheme)
      setThemeState(nextTheme)
    }

    mediaQuery.addEventListener("change", handleChange)
    return () => mediaQuery.removeEventListener("change", handleChange)
  }, [])

  const value: ThemeContextType = {
    theme,
    setTheme,
    toggleTheme,
    isDark: theme === "dark",
  }

  return (
    <ThemeContext.Provider value={value}>{children}</ThemeContext.Provider>
  )
}

export function useTheme(): ThemeContextType {
  const context = useContext(ThemeContext)
  if (context === undefined) {
    throw new Error("useTheme must be used within a ThemeProvider")
  }
  return context
}
