import React, { useEffect, useMemo, useRef, useState } from "react"
import { navigate } from "gatsby"

interface SearchEntry {
  slug: string
  title: string
  tags: string[]
  excerpt: string
  date: string
}

interface SearchModalProps {
  open: boolean
  onClose: () => void
}

const MAX_RESULTS = 8

function SearchModal({
  open,
  onClose,
}: SearchModalProps): React.ReactElement | null {
  const [entries, setEntries] = useState<SearchEntry[] | null>(null)
  const [loadFailed, setLoadFailed] = useState(false)
  const [query, setQuery] = useState("")
  const [activeIndex, setActiveIndex] = useState(0)
  const inputRef = useRef<HTMLInputElement>(null)
  const listRef = useRef<HTMLUListElement>(null)

  // 首次打开才 fetch 索引（不进首屏 bundle），之后缓存在组件状态里
  useEffect(() => {
    if (!open || entries !== null || loadFailed) {
      return
    }
    let cancelled = false
    fetch("/search-index.json")
      .then((res) => {
        if (!res.ok) {
          throw new Error(`HTTP ${res.status}`)
        }
        return res.json()
      })
      .then((data: SearchEntry[]) => {
        if (cancelled) {
          return
        }
        // date 为 "YYYY-MM-DD"，字典序即时间序；预排一次，空查询时展示最新文章
        const sorted = data
          .slice()
          .sort((a, b) => b.date.localeCompare(a.date))
        setEntries(sorted)
      })
      .catch(() => {
        if (!cancelled) {
          setLoadFailed(true)
        }
      })
    return () => {
      cancelled = true
    }
  }, [open, entries, loadFailed])

  // 关闭时重置失败标记：下次打开允许重新 fetch 索引，避免一次失败后永久失能
  useEffect(() => {
    if (!open) {
      setLoadFailed(false)
    }
  }, [open])

  // 打开时：重置输入、聚焦输入框、锁定 body 滚动（参照 PhotoGallery lightbox）
  useEffect(() => {
    if (!open) {
      return
    }
    setQuery("")
    setActiveIndex(0)
    inputRef.current?.focus()
    document.body.style.overflow = "hidden"
    return () => {
      document.body.style.overflow = "unset"
    }
  }, [open])

  // ESC 关闭
  useEffect(() => {
    if (!open) {
      return
    }
    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key === "Escape") {
        event.preventDefault()
        onClose()
      }
    }
    document.addEventListener("keydown", onKeyDown)
    return () => {
      document.removeEventListener("keydown", onKeyDown)
    }
  }, [open, onClose])

  // 打分：标题命中 ×3 + 标签命中 ×2 + 摘要命中 ×1（子串、忽略大小写），取 top 8
  const results = useMemo(() => {
    if (!entries) {
      return []
    }
    const q = query.trim().toLowerCase()
    if (!q) {
      return entries.slice(0, MAX_RESULTS)
    }
    return entries
      .map((entry) => {
        let score = 0
        if (entry.title.toLowerCase().includes(q)) {
          score += 3
        }
        if (entry.tags.some((tag) => tag.toLowerCase().includes(q))) {
          score += 2
        }
        if (entry.excerpt.toLowerCase().includes(q)) {
          score += 1
        }
        return { entry, score }
      })
      .filter((r) => r.score > 0)
      .sort(
        (a, b) => b.score - a.score || b.entry.date.localeCompare(a.entry.date)
      )
      .slice(0, MAX_RESULTS)
      .map((r) => r.entry)
  }, [entries, query])

  // 查询变化后高亮回到第一条
  useEffect(() => {
    setActiveIndex(0)
  }, [query])

  // 键盘移动高亮时保证可见
  useEffect(() => {
    if (!open) {
      return
    }
    const item = listRef.current?.children[activeIndex]
    if (item instanceof HTMLElement) {
      item.scrollIntoView({ block: "nearest" })
    }
  }, [activeIndex, open])

  if (!open) {
    return null
  }

  const go = (entry: SearchEntry) => {
    onClose()
    navigate(entry.slug)
  }

  const onInputKeyDown = (event: React.KeyboardEvent<HTMLInputElement>) => {
    if (event.key === "ArrowDown") {
      event.preventDefault()
      setActiveIndex((i) =>
        results.length === 0 ? 0 : (i + 1) % results.length
      )
    } else if (event.key === "ArrowUp") {
      event.preventDefault()
      setActiveIndex((i) =>
        results.length === 0 ? 0 : (i - 1 + results.length) % results.length
      )
    } else if (event.key === "Enter") {
      event.preventDefault()
      const target = results[activeIndex]
      if (target) {
        go(target)
      }
    }
  }

  return (
    <div
      className="fixed inset-0 z-70 flex items-start justify-center px-4 pt-[12vh] sm:pt-[16vh]"
      role="dialog"
      aria-modal="true"
      aria-label="全站搜索"
    >
      <div
        className="absolute inset-0 bg-background-95"
        onClick={onClose}
        aria-hidden="true"
      />
      <div className="relative w-full max-w-xl rounded-xl bg-background-card shadow-xl overflow-hidden">
        <input
          ref={inputRef}
          type="text"
          value={query}
          onChange={(e) => setQuery(e.target.value)}
          onKeyDown={onInputKeyDown}
          placeholder="搜索文章标题、标签或摘要…"
          aria-label="搜索文章"
          className="w-full px-4 py-3 text-base bg-background-tertiary text-foreground placeholder:text-foreground-subtle outline-hidden focus:ring-1 focus:ring-accent"
        />
        {loadFailed && (
          <p className="px-4 py-6 text-sm text-foreground-muted text-center">
            搜索索引加载失败，请稍后重试
          </p>
        )}
        {!loadFailed && entries === null && (
          <p className="px-4 py-6 text-sm text-foreground-muted text-center">
            正在加载索引…
          </p>
        )}
        {!loadFailed && entries !== null && results.length === 0 && (
          <p className="px-4 py-6 text-sm text-foreground-muted text-center">
            没有匹配的文章
          </p>
        )}
        {results.length > 0 && (
          <ul ref={listRef} className="max-h-80 overflow-y-auto py-2">
            {results.map((entry, index) => (
              <li key={entry.slug}>
                <button
                  type="button"
                  onClick={() => go(entry)}
                  onMouseEnter={() => setActiveIndex(index)}
                  className={`block w-full text-left px-4 py-2.5 ${
                    index === activeIndex ? "bg-accent-subtle" : ""
                  }`}
                >
                  <span className="block text-sm font-medium text-foreground truncate">
                    {entry.title}
                  </span>
                  <span className="mt-0.5 flex items-center gap-2 text-xs text-foreground-muted">
                    <span className="shrink-0">{entry.date}</span>
                    {entry.tags.length > 0 && (
                      <span className="truncate">
                        {entry.tags.join(" / ")}
                      </span>
                    )}
                  </span>
                </button>
              </li>
            ))}
          </ul>
        )}
      </div>
    </div>
  )
}

export default SearchModal
