import React, { useState } from "react"
import { Sun, Moon } from "@phosphor-icons/react"
import { useTheme } from "./ThemeProvider"

export function ThemeToggle(): React.ReactElement {
  const { toggleTheme } = useTheme()
  const [isRotating, setIsRotating] = useState(false)

  const handleClick = () => {
    setIsRotating(true)
    toggleTheme()
    // Reset rotation state after animation completes
    setTimeout(() => setIsRotating(false), 300)
  }

  return (
    <button
      onClick={handleClick}
      className={`
        relative inline-flex items-center justify-center
        w-10 h-10 rounded-lg
        bg-background-secondary
        text-foreground
        hover:bg-background-tertiary hover:shadow-xs hover:text-accent
        transition-all duration-200
        focus:outline-hidden focus:ring-2 focus:ring-accent
        cursor-pointer
      `}
      aria-label="切换主题"
      title="切换主题"
    >
      <span
        className={`
          inline-block transition-transform duration-300 ease-in-out
          ${isRotating ? "rotate-180" : "rotate-0"}
        `}
      >
        <Sun
          weight="duotone"
          size={20}
          className="hidden text-primary dark-theme-icon"
          aria-hidden="true"
        />
        <Moon
          weight="duotone"
          size={20}
          className="light-theme-icon text-primary"
          aria-hidden="true"
        />
      </span>
    </button>
  )
}

export default ThemeToggle
